"""Provide the owned CODE-EVAL-002 mask_suffix fixture."""

import logging

logger = logging.getLogger(__name__)


def mask_suffix(text, count):
    """Keep a proper positive suffix and replace every preceding character with asterisk; mask everything for zero, negative or full-length counts."""
    logger.info("ce002_fixture_called function=mask_suffix")
    if count <= 0 or count >= len(text):
        return "*" * len(text)
    return "*" * (len(text) - count) + text[-count:]
